/* Production controls call the exact MCP engine through the bundled local service. */
let productionBusy=false,productionJob=null,productionAbort=null,productionLast=null,musicDefault=true;
const productionDataURL=blob=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Could not read media.'));r.readAsDataURL(blob);});
async function productionPortable(extra=[]){const used=new Set([...project.clips.map(c=>c.assetId),...extra]),selected=[...assets.values()].filter(a=>used.has(a.id));if(selected.reduce((total,a)=>total+(a.blob?.size||0),0)>512*1024*1024)throw Error('This native job supports up to 512 MB of referenced media. Split the edit into smaller projects.');return {format:'cutline',version:1,project:JSON.parse(snapshot()),assets:await Promise.all(selected.map(async a=>({id:a.id,name:a.name,type:a.type,duration:a.duration,data:await productionDataURL(a.blob)})))};}
async function productionRequest(url,options={}){const response=await fetch(url,options);if(!response.ok){let error='The local production engine is unavailable.';try{error=(await response.json()).error||error;}catch{}throw Error(error);}return response;}
function productionStatus(text){const el=$('#production-status');if(el)el.textContent=text;}
async function applyProductionUpdate(update,signature){if(!update)return;if(snapshot()!==signature)throw Error('The project changed during processing. Your current edit was preserved; run the action again.');const added=[];try{for(const a of update.newAssets){const blob=await fetch(a.data).then(r=>r.blob());await registerAsset({...a,blob});added.push(a.id);}validateProject(update.project,[...assets.values()]);checkpoint();project=update.project;setSelection([]);commit();drawFrame();}catch(error){for(const key of added)assets.delete(key);throw error;}}
async function runProduction(tool,args={},options={}){
 if(exporting||productionBusy||captionBusy||sourceReplacementBusy)return toast('Finish or cancel the current operation first.');
 const signature=snapshot();stop();productionBusy=true;exporting=true;productionAbort=new AbortController();document.body.classList.add('exporting');updateControls();let completed=false;
 try{const cancel=$('#production-cancel');if(cancel)cancel.hidden=false;productionStatus('Preparing · 0%');const portable=await productionPortable(args.assetId?[args.assetId]:[]);if(productionAbort.signal.aborted)throw new DOMException('Cancelled','AbortError');const begin=await productionRequest('/api/production/jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({tool,args,portable,...(options.exportData?{exportData:options.exportData}:{})}),signal:productionAbort.signal});productionJob=(await begin.json()).id;
  while(true){const response=await productionRequest('/api/production/jobs/'+productionJob,{signal:productionAbort.signal}),job=await response.json(),percent=job.status==='done'?100:Math.min(99,job.percent||0),label=(job.phase||'working').replaceAll('-',' ');productionStatus(label+' · '+percent+'%');options.progress?.(label,percent);
   if(job.status==='done'){await applyProductionUpdate(job.updated,signature);productionLast={...job,id:productionJob};completed=true;showProductionResult(productionLast);if(options.download){const target=job.artifacts.findIndex(a=>a.path===job.result.path);if(target<0)throw Error('The verified output artifact is missing.');const file=await productionRequest('/api/production/jobs/'+productionJob+'/files/'+target);download(await file.blob(),options.download);}return job;}
   if(job.status!=='running')throw Error(job.error||'Production '+job.status);await new Promise(r=>setTimeout(r,500));
  }
 }catch(error){productionStatus(error.name==='AbortError'?'Cancelled':error.message);if(error.name!=='AbortError')toast(error.message);throw error;}
 finally{if(productionJob&&!completed)await fetch('/api/production/jobs/'+productionJob+'/cancel',{method:'POST'}).catch(()=>{});productionJob=null;productionAbort=null;productionBusy=false;exporting=false;document.body.classList.remove('exporting');updateControls();renderInspector();syncMedia();drawFrame();const cancel=$('#production-cancel');if(cancel)cancel.hidden=true;}
}
function cancelProduction(){productionAbort?.abort();if(productionJob)fetch('/api/production/jobs/'+productionJob+'/cancel',{method:'POST'}).catch(()=>{});}
function showProductionResult(job){const root=$('#production-results');if(!root)return;root.replaceChildren();const summary=document.createElement('p');summary.className='small-help';const r=job.result,a=r.audio||r.measurement||r;summary.textContent=typeof a.integratedLUFS==='number'?'Loudness '+a.integratedLUFS.toFixed(1)+' LUFS'+(typeof a.truePeakDb==='number'?' · peak '+a.truePeakDb.toFixed(1)+' dB':'')+(r.appliedGainDb!==undefined?' · voice adjusted '+r.appliedGainDb.toFixed(1)+' dB':''):r.asset?r.asset.name+' · '+(r.asset.width?r.asset.width+' × '+r.asset.height:'Audio')+' · '+r.asset.duration.toFixed(1)+' s':r.ok===false?'Check needs attention: '+(r.error||'Review the details below.'):r.files?'Delivery package verified and ready.':r.times?'Contact sheet ready for review.':'Processing complete.';root.append(summary);const details=document.createElement('details'),title=document.createElement('summary'),pre=document.createElement('pre');title.textContent='Detailed report';pre.className='production-report';pre.textContent=JSON.stringify(job.result,null,2);details.append(title,pre);root.append(details);for(const [i,item]of job.artifacts.entries()){const link=document.createElement('a');link.href='/api/production/jobs/'+job.id+'/files/'+i;link.download=item.name;link.className='secondary production-file';link.textContent='Download '+item.name;root.append(link);if(/\.png$/i.test(item.name)){const img=document.createElement('img');img.src=link.href;img.alt='Timeline preview';img.className='production-preview';root.append(img);}}}
async function addProductionMusic(kind='bright',volume=7,assetId=null){if(exporting||captionBusy||productionBusy)return;if(project.locked.audio)return toast('Unlock the audio track first.');try{let a=assetId?assets.get(assetId):null;if(!a){const id='music-'+kind; a=assets.get(id);if(!a)a=await registerAsset({id,name:kind==='calm'?'Cutline · Calm horizon':'Cutline · Bright momentum',type:'audio',blob:new Blob([CutlineProduction.musicWav(64,kind)],{type:'audio/wav'})});}const staged=stageWorkflow(CutlineProduction.musicPlan(project,{...a,hasAudio:true},{volume,replace:true}));commitWorkflow(staged);toast('Music added at '+volume+'% · trimmed to the edit, with fades.');}catch(error){toast(error.message);throw error;}}
addTone=kind=>addProductionMusic(kind==='ambient'?'calm':'bright',7);
const libraryBeforeProduction=renderLibrary;
renderLibrary=function(){libraryBeforeProduction();if(!['audio','ads'].includes(tab))return;const root=$('#library-content');root.insertAdjacentHTML('afterbegin',`<section class="workflow-panel production-panel"><h3>Music & finishing</h3><p class="small-help">Background music starts at 7%. Narration stays in front.</p><label class="field">Music<select id="production-music"><option value="bright">Bright momentum · built-in</option><option value="calm">Calm horizon · built-in</option>${[...assets.values()].filter(a=>a.type==='audio').map(a=>`<option value="asset:${esc(a.id)}">${esc(a.name)}</option>`).join('')}</select></label><label class="field">Music volume · %<input id="production-volume" type="number" min="0" max="100" value="7"></label><button id="production-add-music" class="secondary wide">Add / replace background music</button><div class="pill-row"><button id="production-measure" class="secondary">Measure voice</button><button id="production-master" class="secondary">Balance voice</button></div><label class="field">Inspect source<select id="production-asset">${[...assets.values()].map(a=>`<option value="${esc(a.id)}">${esc(a.name)}</option>`).join('')}</select></label><button id="production-inspect" class="secondary wide">Inspect source & audio</button><div class="pill-row"><button id="production-sheet" class="secondary">Contact sheet</button><button id="production-check" class="secondary">Check footage</button></div><button id="production-verify" class="secondary wide">Verify an exported MP4</button><input id="production-export-file" type="file" accept="video/mp4" hidden><button id="production-bundle" class="primary wide">Export complete delivery ZIP</button><p class="small-help" id="production-status" role="status">Local processing · editable projects included.</p><button id="production-cancel" class="quiet wide" ${productionBusy?'':'hidden'}>Cancel processing</button><div id="production-results"></div></section>`);
 const run=(name,args={})=>{const cancel=$('#production-cancel');if(cancel)cancel.hidden=false;return runProduction(name,args).catch(()=>{});};
 $('#production-add-music').onclick=()=>{const choice=$('#production-music').value;addProductionMusic(choice,Number($('#production-volume').value),choice.startsWith('asset:')?choice.slice(6):null).catch(()=>{});};$('#production-measure').onclick=()=>run('cutline_audio_loudness');$('#production-master').onclick=()=>run('cutline_audio_loudness',{apply:true});$('#production-inspect').onclick=()=>run('cutline_media_inspect',{assetId:$('#production-asset').value,scanVideo:true});$('#production-sheet').onclick=()=>run('cutline_contact_sheet');$('#production-check').onclick=()=>run('cutline_source_check');$('#production-bundle').onclick=()=>runProduction('cutline_delivery_bundle',{height:1920,music:musicDefault,musicVolume:7},{download:slug()+'-delivery.zip'}).catch(()=>{});$('#production-cancel').onclick=cancelProduction;$('#production-verify').onclick=()=>$('#production-export-file').click();$('#production-export-file').onchange=async e=>{const file=e.target.files[0];if(file)try{await runProduction('cutline_export_verify',{}, {exportData:await productionDataURL(file)});}catch{}};if(productionLast)showProductionResult(productionLast);if(exporting||captionBusy)$$('.production-panel button,.production-panel select,.production-panel input').forEach(el=>{if(el.id!=='production-cancel')el.disabled=true;});
};
const showExportBeforeProduction=showExport;
showExport=function(){showExportBeforeProduction();if(!$('#export-music-default')){const label=document.createElement('label');label.className='workflow-check';label.innerHTML='<input id="export-music-default" type="checkbox" checked> Add background music at 7% if none is present';$('.export-options').append(label);$('#export-music-default').onchange=e=>musicDefault=e.target.checked;}$('#export-music-default').checked=musicDefault;};$('#export').onclick=showExport;
const frameExportBeforeProduction=startExport;
startExport=async function(){if(exporting||captionBusy||sourceReplacementBusy)return;let capabilities;try{capabilities=await fetch('/api/capabilities').then(r=>r.json());}catch{}if(musicDefault&&!project.clips.some(c=>c.track==='audio'&&c.audioRole==='music')){try{await addProductionMusic('bright',7);}catch{return;}}
 if(!capabilities?.production||exportSourceEnd!==null||acceptedStillSources.size)return frameExportBeforeProduction();
 $('#export-progress').hidden=false;$('#render-export').hidden=true;$('#cancel-export').hidden=false;for(const el of $$('#export-dialog .close-modal,#export-resolution,#export-format,#export-music-default'))el.disabled=true;
 let sourceNeedsReview=false;try{await runProduction('cutline_render',{format:'mp4',height:Number($('#export-resolution').value),music:musicDefault,musicVolume:7},{download:slug()+'.mp4',progress:(phase,percent)=>{$('#export-progress i').style.width=percent+'%';$('#export-progress span').textContent=phase+' · '+percent+'%';}});toast('Video exported and verified.');$('#export-dialog').close();}catch(error){sourceNeedsReview=/^Source validation failed:/.test(error.message);$('#export-progress span').textContent=error.name==='AbortError'?'Export cancelled.':'Export stopped: '+error.message;}
 finally{for(const el of $$('#export-dialog .close-modal,#export-resolution,#export-format,#export-music-default'))el.disabled=false;$('#render-export').hidden=false;$('#cancel-export').hidden=true;}
 if(sourceNeedsReview)return frameExportBeforeProduction();
};const cancelExportBeforeProduction=cancelExport;cancelExport=function(){if(productionBusy)cancelProduction();else cancelExportBeforeProduction();};$('#render-export').onclick=startExport;$('#cancel-export').onclick=cancelExport;
